<?php
require_once __DIR__.'/../../includes/auth.php';requireSuperAdmin();require_once __DIR__.'/../../includes/functions.php';
if($_SERVER['REQUEST_METHOD']==='POST'){$action=$_POST['action']??'';$id=(int)($_POST['id']??0);try{if($action==='create'){ $name=trim($_POST['full_name']??'');$email=strtolower(trim($_POST['email']??''));$role=$_POST['role']??'Event_Manager';$pass=$_POST['password']??'';if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8)throw new RuntimeException('Name, valid email and password of at least 8 characters are required.');$q=$pdo->prepare('INSERT INTO users(full_name,email,password_hash,role,status) VALUES(?,?,?,?,?)');$q->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT),$role,'Active']);flash('success','Administrator created.');}elseif($action==='toggle'&&$id){$q=$pdo->prepare("UPDATE users SET status=CASE WHEN status='Active' THEN 'Inactive' ELSE 'Active' END WHERE id=? AND id<>?");$q->execute([$id,$_SESSION['user_id']]);flash('success','Administrator status updated.');}elseif($action==='reset'&&$id){$pass=$_POST['new_password']??'';if(strlen($pass)<8)throw new RuntimeException('New password must be at least 8 characters.');$pdo->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($pass,PASSWORD_DEFAULT),$id]);flash('success','Password reset.');}}catch(Throwable $e){flash('danger',$e->getMessage());}redirect('index.php');}
$users=$pdo->query('SELECT id,full_name,email,role,status,last_login_at,created_at FROM users ORDER BY id DESC')->fetchAll();$pageTitle='Administrators';require __DIR__.'/../../includes/header.php';require __DIR__.'/../../includes/sidebar.php';?><main class="main"><?php require __DIR__.'/../../includes/topbar.php';?><section class="content"><?php showFlash();?><div class="d-flex justify-content-between mb-4"><div><span class="section-kicker">SYSTEM</span><h1 class="page-title">Administrators</h1><p class="page-subtitle">Manage privileged access to VoteHub.</p></div></div><div class="row g-4"><div class="col-xl-8"><div class="panel"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>User</th><th>Role</th><th>Status</th><th>Last Login</th><th></th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><strong><?=e($u['full_name'])?></strong><small class="d-block text-muted"><?=e($u['email'])?></small></td><td><?=e($u['role'])?></td><td><span class="badge-soft badge-<?=strtolower($u['status'])?>"><?=e($u['status'])?></span></td><td><?=e($u['last_login_at']??'Never')?></td><td class="text-end"><form method="post" class="d-inline"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$u['id']?>"><button class="btn btn-sm btn-light border" <?=$u['id']==$_SESSION['user_id']?'disabled':''?>>Toggle</button></form></td></tr><?php endforeach;?></tbody></table></div></div></div><div class="col-xl-4"><div class="panel"><div class="panel-head"><h5>Add Administrator</h5></div><div class="panel-body"><form method="post"><input type="hidden" name="action" value="create"><label class="form-label">Full Name</label><input name="full_name" class="form-control mb-3" required><label class="form-label">Email</label><input name="email" type="email" class="form-control mb-3" required><label class="form-label">Role</label><select name="role" class="form-select mb-3"><option>Event_Manager</option><option>Finance_Officer</option><option>Results_Officer</option><option>Auditor</option><option>Super_Admin</option></select><label class="form-label">Temporary Password</label><input name="password" type="password" minlength="8" class="form-control mb-4" required><button class="btn btn-primary w-100">Create Administrator</button></form></div></div></div></div></section></main><?php require __DIR__.'/../../includes/footer.php';?>
